wsc:message.wsc:body:
#[%dw 2.0
output application/xml
ns aut http://maritimasoa.grupo4.pe/autoridadportuaria
---
{
	aut#consultarEstadoPuertoRequest: {
		aut#codigoPuerto: vars.viaje.codigoPuerto,
		aut#fechaZarpe: vars.viaje.fechaZarpe
	}
}]

#[%dw 2.0
output application/xml
ns aut http://maritimasoa.grupo4.pe/autoridadportuaria
---
{
	aut#validarMigracionPasajeroRequest: {
		aut#numeroPasaporte: vars.solicitud.numeroPasaporte default '',
		aut#documentoIdentidad: vars.solicitud.documentoPasajero,
		aut#paisDestino: vars.viaje.paisDestino
	}
}]
